fn reverse_string(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate a new vector with the same length as the input
    let mut result = Vec::with_capacity(s.len());
    // Iterate over the input in reverse order and push each character
    for &ch in s.iter().rev() {
        result.push(ch);
    }
    result
}

